  const port = match[2] ? Number(match[2]) : 443;
  if (port < 1 || port > 65535 || port !== 443 && !/\.hath\.network$/i.test(match[1])) fail('图片 HTTPS 端口不受支持');
  if (/\/(?:g\/)?509\.(?:gif|jpg|png)(?:\?|$)/i.test(match[3])) fail('图片额度已用尽，请稍后重试');
  return url;
}
async function imageFromPage(url) {
  const doc = await fetchHtml(url), src = await triomi.value(doc, 'img#img', 'src');
  const visible = await triomi.value(doc, 'body', 'text') || '';
  if (/(?:exceeded|reached).*?(?:limit|quota)|temporarily banned/i.test(visible)) fail('图片额度已用尽或访问暂时受限');
  if (!src) fail('未返回公开图片，可能需要登录或内容已删除');
  return readableImage(src);
}
async function content(url) {
  const match = /^(https:\/\/e-hentai\.org\/g\/[1-9][0-9]*\/[a-f0-9]{10}\/)\?triomi_start=([1-9][0-9]*)&triomi_total=([1-9][0-9]*)$/.exec(url);
  if (!match) fail('章节地址无效，请刷新图库目录');
