    for (const link of links) {
      const pageUrl = absolute(link), row = /^https:\/\/e-hentai\.org\/s\/([a-f0-9]+)\/([1-9][0-9]*)-([1-9][0-9]*)$/.exec(pageUrl);
      if (!row || row[2] !== ref.id) fail('图片页图库身份不匹配');
      const n = Number(row[3]);
      if (n > total || pages.has(n) || seen.has(pageUrl)) fail('图片页重复或编号无效');
      pages.set(n, pageUrl); seen.add(pageUrl);
    }
  }
  add(firstLinks);
  for (let n = 1; n <= perPage; n++) if (!pages.has(n)) fail('首页图片序号不连续');
