    const doc = await fetchHtml(ref.url + '?p=' + p);
    if (await gallerySize(doc) !== total) fail('图库已变化，请刷新目录');
    add(await triomi.values(doc, '#gdt a[href], .gdtm a[href]', 'href'));
  }
