  for (let n = start; n <= end; n++) {
    if (!pages.has(n)) fail('章节图片页列表不完整，请刷新');
    images.push(await imageFromPage(pages.get(n)));
  }
  return {images: images, imageHeaders: {'Referer': BASE + '/', 'User-Agent': 'Mozilla/5.0'}};
}
